INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT144-S4-Q1$batch11$, 144, 4, 1, $batch11$Sufficient Assumption$batch11$, $batch11$Aisha: Vadim is going to be laid off. Vadim’s work as a programmer has been exemplary since joining the firm. But management has already made the decision to lay off a programmer. And this firm strictly follows a policy of laying off the most recently hired programmer in such cases.$batch11$, $batch11$Aisha’s conclusion follows logically if which one of the following is assumed?$batch11$, $batch11$C$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$The firm values experience in its programmers more highly than any other quality.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$When Vadim was hired, the policy of laying off the most recently hired programmer was clearly explained.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Vadim is the most recently hired programmer at the firm.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Every other programmer at the firm has done better work than Vadim.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$It is bad policy that the firm always lays off the most recently hired programmer.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Vadim is going to be laid off.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Management has decided to lay off a programmer. The firm always lays off the most recently hired programmer.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The policy picks the most recently hired programmer. Nothing yet says that's Vadim. Connect Vadim to the policy and the conclusion follows.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Vadim is the most recently hired programmer.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$What the firm values doesn't change the strict layoff policy, and still doesn't name Vadim.$batch11$), ($batch11$B$batch11$, $batch11$Whether the policy was explained to Vadim doesn't make Vadim the one laid off.$batch11$), ($batch11$C$batch11$, $batch11$The firm lays off the most recent hire. If that's Vadim, Vadim is laid off.$batch11$), ($batch11$D$batch11$, $batch11$The policy is based on hiring order, not work quality.$batch11$), ($batch11$E$batch11$, $batch11$Whether the policy is good doesn't change whom it selects.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT144-S4-Q1$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
